-- Sample seed data for courier_db (MySQL 8)
-- Creates 1 admin, 20 delivery boys, 100 customers, 100 parcels, deliveries and tracking history.
USE courier_db;

SET FOREIGN_KEY_CHECKS = 1;







-- Quick verification queries
SELECT COUNT(*) AS total_customers FROM customers;
SELECT COUNT(*) AS total_parcels FROM parcels;
SELECT COUNT(*) AS total_deliveries FROM deliveries;
SELECT COUNT(*) AS total_history_rows FROM delivery_status_history;
